# Janet Lecompte, « Charles Autobees », The Colorado Magazine, feuilleton paru de juillet 1957 à 1959.
# Deux livraisons du Drive de l'auteur (HISTOIRE_LIVRES/CHARLES_AUTOBEES), lues en entier le 19 novembre 2026 :
#   vol. 34, no 3 (juillet 1957), chap. I-II, p. 163-179 ; vol. 35, no 4 (octobre 1958), chap. IX, p. 303-308.
# Corpus « Recherches », préfixe LA57. Seuls les épisodes absents de l'atlas sont retenus
# (naissance, Salmon, Wolf Den, moulin de Turley, Sand Creek, plaza du Huerfano sont déjà couverts : C010-C163).
from commun import Corpus
S1 = "Lecompte, Janet (1957), « Charles Autobees » (chap. I-II), The Colorado Magazine, vol. 34, no 3 (juillet), p. 163-179"
S9 = "Lecompte, Janet (1958), « Charles Autobees » (chap. IX), The Colorado Magazine, vol. 35, no 4 (octobre), p. 303-308"
C = Corpus('Recherches', 'LA57', S1, page_fmt='p. {}')
F = C.F
A = ['Charles Autobees']

# ---- Chapitres I et II (1957)
F('01', "Fort Tecumseh : Pierre Ortubise, batelier et guide de Maximilien (1830-1833)", 'personne', '1830/1833', -100.37, 44.38, 'a', ['Pierre Ortubise', 'Maximilien de Wied'],
  "Cherchant la trace d'Autobees dans les registres de l'American Fur Company du haut Missouri, Lecompte ne trouve qu'un nom approchant : Pierre Ortubise, Métis et batelier au fort Tecumseh, qui servit de guide au prince Maximilien de Wied en 1833. Elle le tient pour un parent très possible de Charles, dont le nom s'écrivait aussi Ortubiz, Ortibi, Ortivis ou Audeby.",
  '167', "Lien de parenté conjectural.")
F('02', "Bent's Stockade (embouchure de la Fontaine) : Autobees témoin de la visite de Bull Hump (1826-1828, selon George Bent)", 'evenement', '1826/1828', -104.6, 38.255, 'h', A + ['George Bent', 'William Bent', 'Bull Hump'],
  "George Bent raconte que Charles Autobees, alors chasseur de castor pour les Bent, lui a décrit le passage du chef comanche Bull Hump au petit fortin de pieux où son père cachait des Cheyennes parmi les marchandises ; les Comanches allèrent ensuite voler des chevaux dans un camp cheyenne de la Platte Sud. Lecompte montre que Bent situe ce fortin tantôt à la Purgatoire, tantôt à la Huerfano ou à Pueblo, et le date de 1826 à 1834 ; Autobees lui-même jura en 1873 n'être venu dans le pays qu'en 1837. Il a pu tenir l'histoire de son beau-frère Guadalupe Ávila, qui moulait les adobes du fort de Gantt en mai 1833.",
  '170-171', "Témoignage tardif et contradictoire. Point à l'embouchure de la Fontaine, l'une des localisations de George Bent.")
F('03', "Rivière Greenhorn : Autobees dit connaître le pays depuis 1837 (témoignage de Pueblo, 16 janvier 1873)", 'personne', '1837', -104.52, 38.2, 'a', A + ['Irving W. Stanton', 'Estefana Hicklin'],
  "Entendu le 16 janvier 1873 devant le registraire du bureau foncier de Pueblo, dans la réclamation d'Estefana Hicklin sur la concession Vigil et St. Vrain, Autobees, qui se dit âgé de soixante ans, déclare être arrivé dans « ce pays » en 1837 et connaître depuis lors la fourche Greenhorn de la Saint-Charles, qui rejoint l'Arkansas à six milles en aval de Pueblo. Lecompte retient ce serment contre la tradition qui le fait participer à la construction du fort Bent.",
  '169', "Point au confluent Greenhorn-Saint-Charles.")
F('04', "Colony (Oklahoma) : Picking Bones Woman, l'épouse cheyenne d'Autobees, et leur fils John Ortebee (vers 1902)", 'personne', '1902~', -98.67, 35.35, 'a', A + ['Picking Bones Woman', 'John Ortebee', 'George Bird Grinnell'],
  "Dans les années 1830, Autobees prit une épouse cheyenne, Picking Bones Woman, dont il eut un fils, John Ortebee ou Otterby. Il la laissa à sa tribu en s'installant à Taos. Au début des années 1900, George Bird Grinnell interrogea la vieille femme dans la réserve des Cheyennes du Sud, à Colony ; John y vivait aussi et travaillait par intermittence pour le Service indien.",
  '172', "")
F('05', "Taos et Pueblo : Juan de Dios Autobees, fils métis de Charles, vigneron puis juge de paix (1858-1873)", 'personne', '1858/1873', -105.573, 36.407, 'c', A + ['Juan de Dios Autobees'],
  "Le fils cheyenne d'Autobees est probablement le Juan de Dios Autobees qui vécut avec la famille à Rio Colorado dans les années 1850, puis sur la Huerfano. Il obtient une licence de vigneron dans le comté de Taos en 1858, est juge de paix du comté de Pueblo en 1868 et figure parmi les contribuables en retard en 1873. On perd ensuite sa trace ; il n'est pas compté parmi les héritiers de Charles.",
  '172', "Point à Taos (licence de 1858).")
F('06', "Taos : mariage de Carlos Ortivis et de Serafina Ávila par le padre Martínez (28 novembre 1842)", 'evenement', '1842-11-28', -105.573, 36.407, 'c', A + ['Serafina Ávila', 'Antonio José Martínez', 'Pascual Martínez'],
  "Le 28 novembre 1842, le curé de Taos Antonio José Martínez marie Charles Autobees à Serafina Ávila (Abila), fille de feu Juan de Jesús Ábila et de María Antonia Pacheco, d'Abiquiú, probablement après la naissance de leur deuxième fils. Parrains : Pascual Martínez, frère du padre, et María Teodora Gallegos. Au registre, Charles se dit fils de Francisco Ortibi et de Serafina Feyta. Le couple eut cinq enfants : Mariano (1837), José María (1842), Francisquita (1845), Manuelita (1846) et Tomás (1849). Serafina mourut d'hydropisie en novembre 1871.",
  '164, 172-173', "")
F('07', "Plaza de Dolores (Arroyo Hondo) : les Ortivi dans les registres de Taos (1844-1849)", 'personne', '1844-11-03/1849-07-04', -105.67, 36.535, 'c', A + ['Tom Tobin', 'Tomás Autobees', 'Serafina Ávila'],
  "Le 3 novembre 1844, « Tomás Ortivi, fils de Francisco Ortivi et de María Serafina Abeita », épouse à la Plaza de Dolores María Pascuala Bernal : c'est Tom Tobin, demi-frère de Charles, qui se dira plus tard simple « frère par alliance ». En septembre 1848, Carlos Ortivis et Serafina Ábila sont parrain et marraine de son fils José Narciso. Le 4 juillet 1849, le padre Martínez baptise, âgé de huit jours, José Tomás, fils de Carlos Ortivis et de Serafina Ábila, de la Plaza de Dolores ; ses grands-parents paternels sont donnés comme Juan Ortivi et Carlota Rist.",
  '164-165, 175', "")
F('08', "Fort Bent : « Tom Otobus » guide l'avant-garde de la caravane de Webb vers Taos ; Charles dédouane le chariot de Turley à Santa Fe (1845)", 'evenement', '1845-06/1845-08-30', -103.43, 38.04, 'a', A + ['Tom Tobin', 'James J. Webb', 'Simeon Turley'],
  "Au printemps 1845, Autobees mène vers l'est un chariot de Simeon Turley et revient en août avec des marchandises valant 759,48 $, déclarées à la douane de Santa Fe le 30 août. Il voyage sans doute dans la caravane de James J. Webb, qui, pour éviter des guérilleros texans, passe par le fort Bent. Six hommes y sont détachés vers Santa Fe par la piste de Taos ; leur guide et capitaine est le jeune « Tom Otobus », Tom Tobin, que Webb laisse chez Turley à Arroyo Hondo.",
  '175-176', "")
F('09', "Concession de La Lama (Cebolla), entre Rio Colorado et San Cristóbal : Carlos et Tomás Ortivis mis en possession (20 mars 1846)", 'lieu', '1845-12-31/1846-03-20', -105.62, 36.63, 'c', A + ['Tom Tobin', 'Juan Carlos Santistevan', 'Manuel Armijo', 'Juan Lorenzo Martínez'],
  "Le 31 décembre 1845, Juan Carlos Santistevan et quatre compagnons de Dolores demandent au gouverneur Armijo une terre vacante entre le Rio Colorado et le ruisseau San Cristóbal. Le 20 mars 1846, l'alcalde de Dolores les prend par la main, les y installe « au nom de Dieu et des sages lois mexicaines », et les bénéficiaires arrachent l'herbe et lancent des pierres en criant leur joie. Les noms de Carlos et Tomás Ortivis n'apparaissent que dans cet acte de possession. Les bornes ne furent jamais posées, à cause du mauvais temps et des fourrés ; la concession, d'environ 50 000 acres, fut enregistrée sous le nom de Cebolla.",
  '176-178', "Point au centre approximatif de la concession.")
F('10', "Taos : le procès « Ortubise contre Lucero », champ de bataille de Charles Bent et du padre Martínez (mars-mai 1846)", 'evenement', '1846-03-20/1846-05-01', -105.573, 36.407, 'a', A + ['Charles Bent', 'Antonio José Martínez', 'Juan Manuel Lucero', 'Stephen Louis Lee', 'Cornelio Vigil'],
  "Le jour même de la prise de possession, Armijo renvoie devant l'alcalde de Taos un procès entre « Ortubise » et Juan Manuel Lucero, beau-frère du padre Martínez, dont la famille possède des terres à San Cristóbal. Le shérif Stephen Louis Lee choisit Cornelio Vigil comme arbitre ; Lucero le récuse, et quand le padre vient le défendre, le juge Valdez le renvoie à son église. Le 1er avril, Bent écrit que « Lee et Ortibise partent aujourd'hui pour les États-Unis par le col de Sangre de Cristo » ; le 1er mai, il prédit qu'Ortibise gagnera et que le prêtre ira peut-être en prison.",
  '178-179', "Objet du procès inconnu ; Lecompte le rattache à la concession de La Lama.")

# ---- Chapitre IX (1958)
F('11', "Ranch d'Albert G. Boone : Autobees et les chevaux volés par les Cheyennes et les Arapahos (septembre 1864)", 'evenement', '1864-08-12/1864-09-28', -104.38, 38.25, 'a', A + ['Albert G. Boone'],
  "Vers le 20 septembre 1864, au ranch d'Albert G. Boone sur l'Arkansas, Autobees parlemente avec des Cheyennes et des Arapahos, qui reconnaissent lui avoir pris dix-neuf chevaux le 12 août. Au conseil de Camp Weld, le 28 septembre, les Arapahos désignent le fils de Raven comme voleur. Lecompte relie ces déprédations à la marche de Chivington sur Sand Creek, où Autobees guide les volontaires, aperçoit un de ses poneys et sauve une Indienne.",
  '303', "Point approximatif à Booneville.", source=S9)
F('12', "Plaza d'Autobees : Mariano Autobees et les soixante-six poneys de Sand Creek (novembre-décembre 1864)", 'evenement', '1864-11/1864-12', -104.37, 38.205, 'a', A + ['Mariano Autobees'],
  "Lieutenant dans la compagnie H du 3e régiment de volontaires du Colorado, Mariano, fils aîné de Charles, conduit au fort Lyon un troupeau de poneys pris aux Cheyennes, puis repart sans autorisation avec soixante-six d'entre eux vers le ranch de son père. Un détachement de soldats vient les reprendre pour les ramener au fort. Une arrière-petite-fille de Charles, Eloisa Sanchez, donna à la Société historique onze certificats de libération de « soldats de cent jours » conservés dans la famille.",
  '303-304', "", source=S9)
F('13', "Booneville : les Autobees signent pour les soldats de Camp Fillmore contre William Craig (12 octobre 1865)", 'evenement', '1865-10-12/1865-11-14', -104.38, 38.25, 'a', A + ['Mariano Autobees', 'John Autobees', 'Manuel Autobees', 'William Craig'],
  "À l'élection de 1865, où Sand Creek est l'enjeu principal, le Rocky Mountain News attaque le démocrate William Craig en publiant sa plainte contre les vols des soldats de Camp Fillmore, puis un témoignage de bonne conduite daté de Booneville le 12 octobre 1865, signé par « Charles Autubees », « Marino Autubees », « John Autubees » et « Manuel Autubees » (ou en leur nom). Craig, « copperhead », est battu.",
  '304', "Point approximatif à Booneville.", source=S9)
F('14', "Basse Huerfano : l'acte de William Craig donne à Autobees les sections 12 et 13 (5 décembre 1865)", 'lieu', '1865-12-05/1866-01-10', -104.385, 38.19, 'c', A + ['William Craig', 'Ceran St. Vrain', 'W. J. Thompson'],
  "Fondé de pouvoir de Ceran St. Vrain, William Craig cède pour cinq dollars à « Charles Autubis », en récompense d'avoir été l'un des premiers colons de la concession de Las Animas et d'y être resté malgré la guerre indienne, un mille et demi de terres irrigables de la Huerfano, à un mille et quart de son confluent avec l'Arkansas : les sections 12 et 13 de la basse Huerfano, d'après l'arpentage de Thomas Means. L'acte est enregistré le 10 janvier 1866. Il exclut les quelque 500 acres de l'embouchure qu'Autobees cultivait depuis 1853 avec le fossé Doyle-Wootton ; Lecompte n'écarte pas une escroquerie de Craig.",
  '304-306', "Point approximatif un mille en amont de l'embouchure.", source=S9)
F('15', "Fort Reynolds : Autobees pique le site du poste avec Marcy, puis dispute ses terres à l'armée (1867-1868)", 'evenement', '1867-04/1868-04-16', -104.33, 38.22, 'c', A + ['Randolph B. Marcy', 'William Craig', 'Wilbur F. Stone', 'Charles A. Curtis', 'George Markham'],
  "Au printemps 1867, l'inspecteur général Marcy fixe l'emplacement du fort Reynolds sur la falaise sud de l'Arkansas, à deux milles et demi de la plaza d'Autobees ; si les piquets disparaissent, écrit-il, « le capitaine Craig et Charles Audeby » sauront les replacer. Le 12 juin, Craig loue aux États-Unis près de 23 milles carrés de la concession, y compris les 500 acres de l'embouchure. Autobees charge l'avocat Wilbur F. Stone de le défendre ; la plainte remonte jusqu'à Sherman et Grant. L'ordre spécial no 20 du capitaine Curtis (11 février 1868) chasse les squatters et vise le débit de whisky qu'Autobees loue près du poste ; l'ordre no 49 (16 avril) permet finalement à Autobees et à George Markham de cultiver les terres de l'embouchure.",
  '306-308', "", source=S9)
F('16', "Plaza d'Autobees : saloon, salle de bal et fandango tragique chez « French Joe », gendre d'Autobees (10 octobre 1868)", 'evenement', '1867-10/1868-10-12', -104.37, 38.205, 'a', A + ['French Joe', 'John H. Price', 'George H. Greenland'],
  "À l'arrivée de la garnison du fort Reynolds, Autobees aménage dans sa plaza un saloon et une salle de bal, où Mexicains et simples soldats font la fête pendant que les officiers dansent le quadrille au fort. Au fandango donné sur la Huerfano le samedi 10 octobre 1868 par French Joe, gendre de Charley Autobees, un Mexicain tire sur un soldat ivre qui riposte ; le charpentier du fort John H. Price, voulant le désarmer, reçoit une balle et meurt le lundi suivant.",
  '308', "", source=S9)
fiches = C.fiches
